class Stack<T> {
  private items: T[] = [];

  push(item: T): this {
    this.items.push(item);
    return this;
  }

  pop(): T | undefined {
    return this.items.pop();
  }

  get size(): number {
    return this.items.length;
  }
}

const s = new Stack<number>().push(1).push(2).push(3);
s.pop();
console.log(s.size, s.pop());

