async function main() {
  const results = await Promise.allSettled([
    Promise.resolve(1),
    Promise.reject(new Error("boom")),
    Promise.resolve(3),
  ]);

  const summary = results.map((r) =>
    r.status === "fulfilled" ? r.value : `err:${r.reason.message}`,
  );
  console.log(summary);
}

main();

